def _axisSpacing(self, d):
    """Return the representative per-cell spacing of an axis.

    `d` is either a scalar (uniform axis) or an array of per-cell
    spacings (graded axis).  For a graded axis the representative
    spacing is the arithmetic mean of the individual cell sizes, which
    reduces to the common cell size when the axis is uniform.
    """
    if numerix.shape(d) == ():
        return d
    return numerix.sum(d) / len(d)

